import sqlite3
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/add_product', methods=['POST'])
def add_product():
    name = request.form.get('product_name')
    price_str = request.form.get('product_price')

    if not name or price_str is None:
        return jsonify({'status': 'error', 'message': 'Missing fields'}), 400

    try:
        price = float(price_str)
    except ValueError:
        return jsonify({'status': 'error', 'message': 'Invalid price'}), 400

    if price <= 0:
        return jsonify({'status': 'error', 'message': 'Price must be positive'}), 400

    try:
        with sqlite3.connect('inventory.db') as conn:
            cursor = conn.cursor()
            cursor.execute("INSERT INTO products (name, price) VALUES (?, ?)", (name, price))
            conn.commit()
        return jsonify({'status': 'ok', 'message': 'Product added'}), 201
    except sqlite3.Error as e:
        return jsonify({'status': 'error', 'message': str(e)}), 500

import sqlite3
from flask import Flask, jsonify
import logging

app = Flask(__name__)

logging.basicConfig(
    filename='app.log',
    level=logging.ERROR,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

@app.route('/api/products', methods=['GET'])
def list_products():
    try:
        with sqlite3.connect('inventory.db') as conn:
            conn.row_factory = sqlite3.Row
            cursor = conn.cursor()
            cursor.execute("SELECT * FROM products")
            products = [dict(row) for row in cursor.fetchall()]
        return jsonify(products)
    except sqlite3.Error as e:
        logging.error(f"Database error in list_products: {e}")
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/api/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    try:
        with sqlite3.connect('inventory.db') as conn:
            conn.row_factory = sqlite3.Row
            cursor = conn.cursor()
            cursor.execute("SELECT * FROM products WHERE id = ?", (product_id,))
            row = cursor.fetchone()
            if row is None:
                return jsonify({'error': 'Product not found'}), 404
            return jsonify(dict(row))
    except sqlite3.Error as e:
        logging.error(f"Database error in get_product: {e}")
        return jsonify({'error': 'Internal server error'}), 500
